<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\FeedbackMessage;use Illuminate\Http\Request;class FeedbackController extends Controller{public function index(Request $r){$q=FeedbackMessage::latest();if($r->filled('status'))$q->where('status',$r->status);return view('admin.feedback.index',['items'=>$q->paginate(50)]);}public function show(FeedbackMessage $feedback){if($feedback->status==='new')$feedback->update(['status'=>'read']);return view('admin.feedback.show',['item'=>$feedback]);}public function update(Request $r,FeedbackMessage $feedback){$feedback->update($r->validate(['status'=>'required|in:new,read,answered,closed']));return back()->with('ok','Статус изменён');}public function destroy(FeedbackMessage $feedback){$feedback->delete();return redirect()->route('admin.feedback.index');}}